<template><view class="page"><view class="wrap"><MobileHeader title="公共配置" back-icon-name="chevron-left"/><view class="card"><view class="field"><text>配置键名</text><input v-model="key" placeholder="请输入配置键名"/></view><button class="primary" :disabled="busy" @tap="load">读取配置</button></view><view v-if="value!==undefined" class="card"><text selectable>{{value===null?'未找到公开配置':value}}</text></view><text class="error">{{error}}</text></view></view></template><script setup lang="ts">import {ref} from 'vue';import MobileHeader from '@/components/MobileHeader.vue';import {client,requireSession} from '@/platform';const key=ref(''),value=ref<unknown>(),busy=ref(false),error=ref('');async function load(){if(!requireSession())return;if(!key.value.trim()){error.value='请输入配置键名';return;}busy.value=true;error.value='';try{value.value=await client.config(key.value.trim());}catch{error.value='配置读取失败，或该配置不允许公开访问';}finally{busy.value=false;}}</script><style scoped lang="scss">.page{min-height:100vh;background:#f7f8fc;padding-bottom:calc(110px + env(safe-area-inset-bottom))}.wrap{max-width:500px;margin:auto;padding:0 15px}.section-title{font-size:17px;font-weight:600}.card{background:#fff;border-radius:18px;padding:18px;margin-top:14px;box-shadow:0 6px 16px rgba(20,31,51,.06)}.row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0;border-bottom:1px solid #eef1f6}.row:last-child{border:0}.muted{color:#8791a4;font-size:12px}.primary{margin-top:20px;background:#294fdb;color:white;border-radius:12px;font-size:14px}.field{padding:15px 0;border-bottom:1px solid #eef1f6}.field text{display:block;font-size:13px;color:#636e82;margin-bottom:10px}.field input{font-size:14px}.empty{padding:36px 0;text-align:center;color:#8791a4;font-size:14px}.badge{color:#294fdb;font-size:12px}.error{color:#d44545;font-size:13px;margin-top:12px}</style>
